const ListPurchasesForExport = `-- name: ListPurchasesForExport :many
SELECT p.id,
    p.purchased_at,
    p.refunded_at,
    p.price_at_purchase,
    COALESCE(p.refunded_amount, 0)::bigint AS refunded_amount,
    p.currency,
    p.kind,
    p.episode_id,
    p.volume_id,
    p.series_bundle_id,
    p.coin_pack_id,
    p.provider,
    p.provider_checkout_id,
    p.provider_payment_id,
    p.store,
    p.store_transaction_id,
    p.is_test,
    (
        p.purchased_at >= $1
        AND p.purchased_at < $2
    )::boolean AS purchased_in_period,
    (
        COALESCE(p.refunded_amount, 0) > 0
        AND (
            (
                p.refunded_at >= $1
                AND p.refunded_at < $2
            )
            OR (
                p.refunded_at IS NULL
                AND p.purchased_at >= $1
                AND p.purchased_at < $2
            )
        )
    )::boolean AS refunded_in_period
FROM purchases p
WHERE p.tenant_id = $3
    AND (
        p.store IS NOT NULL
        OR (
            p.provider IS NOT NULL
            AND p.provider <> 'coins'
        )
    )
    AND (
        (
            p.purchased_at >= $1
            AND p.purchased_at < $2
        )
        OR (
            p.refunded_at >= $1
            AND p.refunded_at < $2
        )
    )
ORDER BY p.purchased_at,
    p.id
`

